const toClient = doc => { const value = doc.toObject ? doc.toObject() : doc; const { password, googleSubject, otpHash, otpPurpose, otpExpiresAt, ...safe } = value; return { ...safe, id: String(value._id), createdAt: value.createdAt || new Date().toISOString() }; };
const JWT_SECRET = process.env.JWT_SECRET;
const PASSWORD_HASH_ROUNDS = 10;
const authLimiter = rateLimit({windowMs:15*60*1000,limit:8,standardHeaders:'draft-8',legacyHeaders:false,message:{success:false,msg:'Bạn đã thử quá nhiều lần. Vui lòng thử lại sau 15 phút.'}});
const otpLimiter = rateLimit({windowMs:15*60*1000,limit:5,standardHeaders:'draft-8',legacyHeaders:false,keyGenerator:req=>`${rateLimit.ipKeyGenerator(req.ip)}:${cleanEmail(req.body?.email)}`,message:{success:false,msg:'Bạn đã yêu cầu OTP quá nhiều lần. Vui lòng thử lại sau 15 phút.'}});
const emailPattern=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const cleanEmail=value=>String(value||'').trim().toLowerCase();
const validPassword=value=>typeof value==='string'&&value.length>=8&&value.length<=72;
const makeToken=user=>{if(!JWT_SECRET)throw new Error('JWT_SECRET chưa được cấu hình trên máy chủ.');return jwt.sign({sub:String(user._id),email:user.email,role:user.role,sv:user.sessionVersion||0},JWT_SECRET,{expiresIn:'7d',issuer:'psifu-api'});};
const requireAuth=async(req,res,next)=>{try{if(!JWT_SECRET)return res.status(503).json({success:false,msg:'Máy chủ chưa cấu hình JWT_SECRET.'});const token=String(req.headers.authorization||'').replace(/^Bearer\s+/i,'');if(!token)return res.status(401).json({success:false,msg:'Bạn cần đăng nhập để tiếp tục.'});const payload=jwt.verify(token,JWT_SECRET,{issuer:'psifu-api'});const user=await User.findById(payload.sub).select('email role sessionVersion');if(!user||user.email!==payload.email||(user.sessionVersion||0)!==(payload.sv||0))return res.status(401).json({success:false,msg:'Phiên đăng nhập không còn hiệu lực. Vui lòng đăng nhập lại.'});req.auth={...payload,role:user.role,email:user.email};next();}catch{return res.status(401).json({success:false,msg:'Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.'});}};
const requireRole=(...roles)=>(req,res,next)=>roles.includes(req.auth?.role)?next():res.status(403).json({success:false,msg:'Bạn không có quyền thực hiện thao tác này.'});
const pageResult = async (Model, filter, req, res) => { const page=Math.max(1,Number(req.query.page)||1),limit=Math.min(100,Math.max(1,Number(req.query.limit)||20)); const [items,total]=await Promise.all([Model.find(filter).sort({createdAt:-1}).skip((page-1)*limit).limit(limit),Model.countDocuments(filter)]); res.json({items:items.map(toClient),pagination:{page,limit,total,totalPages:Math.ceil(total/limit)}}); };
const requireSelfOrAdmin=(field='email')=>(req,res,next)=>cleanEmail(req.params[field]||req.body[field])===req.auth?.email||req.auth?.role==='admin'?next():res.status(403).json({success:false,msg:'Bạn chỉ được thao tác trên tài khoản của chính mình.'});
const requireChatParticipant=async(req,res,next)=>{const roomId=String(req.params.roomId||'');if(!roomId.startsWith('mentor-chat-'))return next();const matched=roomId.match(/^mentor-chat-([^-]+)-/);if(!matched)return res.status(403).json({success:false,msg:'Phòng trò chuyện không hợp lệ.'});let mentorEmail;try{mentorEmail=cleanEmail(decodeURIComponent(matched[1]));}catch{return res.status(403).json({success:false,msg:'Phòng trò chuyện không hợp lệ.'});}if(req.auth.role==='admin'||req.auth.email===mentorEmail)return next();if(await Booking.exists({mentorEmail,menteeEmail:req.auth.email,status:{$ne:'Đã hủy'}}))return next();return res.status(403).json({success:false,msg:'Bạn không có quyền truy cập cuộc trò chuyện này.'});};
io.use(async(socket,next)=>{try{const token=String(socket.handshake.auth?.token||'');const payload=jwt.verify(token,JWT_SECRET,{issuer:'psifu-api'});const user=await User.findById(payload.sub).select('email role sessionVersion');if(!user||user.email!==payload.email||(user.sessionVersion||0)!==(payload.sv||0))return next(new Error('unauthorized'));socket.user={email:user.email,role:user.role};next();}catch{next(new Error('unauthorized'));}});
io.on('connection',socket=>{socket.on('chat:join',roomId=>{const room=String(roomId||'');if(room==='homepage-live'||room.includes('::'))socket.join(room);});});
const mailer = process.env.SMTP_HOST ? nodemailer.createTransport({ host: process.env.SMTP_HOST, port: Number(process.env.SMTP_PORT || 587), secure: process.env.SMTP_SECURE === 'true', auth: process.env.SMTP_USER ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS } : undefined, connectionTimeout: 15000, greetingTimeout: 15000, socketTimeout: 20000 }) : null;
const hashOtp = code => crypto.createHash('sha256').update(code).digest('hex');
const sendEmail = async ({to,subject,text,html}) => { if(process.env.RESEND_API_KEY){ const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${process.env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:process.env.RESEND_FROM||'PSIFU <onboarding@resend.dev>',to:[to],subject,text,html})}); const result=await response.json().catch(()=>({})); if(!response.ok)throw new Error(result.message||result.name||'Resend không thể gửi email.'); return result; } if(!mailer)throw new Error('Chưa cấu hình RESEND_API_KEY hoặc SMTP.'); return mailer.sendMail({from:process.env.SMTP_FROM||process.env.SMTP_USER,to,subject,text,html}); };
const payosConfigured = () => Boolean(process.env.PAYOS_CLIENT_ID && process.env.PAYOS_API_KEY && process.env.PAYOS_CHECKSUM_KEY && process.env.PAYOS_RETURN_URL && process.env.PAYOS_CANCEL_URL);
const cloudinaryConfigured = () => Boolean(process.env.CLOUDINARY_CLOUD_NAME && process.env.CLOUDINARY_API_KEY && process.env.CLOUDINARY_API_SECRET);
const cloudinarySignature = params => crypto.createHash('sha1').update(`${Object.keys(params).sort().map(key=>`${key}=${params[key]}`).join('&')}${process.env.CLOUDINARY_API_SECRET}`).digest('hex');
const payosSignature = data => crypto.createHmac('sha256', process.env.PAYOS_CHECKSUM_KEY || '').update(Object.keys(data || {}).sort().filter(key => data[key] !== undefined && data[key] !== null).map(key => `${key}=${data[key]}`).join('&')).digest('hex');
const payosRequest = async (path, options = {}) => { const response = await fetch(`https://api-merchant.payos.vn${path}`, { ...options, headers:{ 'Content-Type':'application/json', 'x-client-id':process.env.PAYOS_CLIENT_ID, 'x-api-key':process.env.PAYOS_API_KEY, ...(options.headers||{}) } }); const payload = await response.json().catch(() => ({})); if (!response.ok || payload.code && payload.code !== '00') throw new Error(payload.desc || 'PayOS không thể xử lý yêu cầu thanh toán.'); return payload.data; };
const nextPayosOrderCode = async () => { for(let attempts=0;attempts<8;attempts+=1){ const code=Number(`${Date.now().toString().slice(-8)}${crypto.randomInt(10,100)}`); if(!await PaymentOrder.exists({orderCode:code})) return code; } throw new Error('Không thể tạo mã đơn thanh toán.'); };
const issueOtp = async (user, purpose) => { const code = crypto.randomInt(100000, 1000000).toString(); const title=purpose === 'verify-email' ? 'Xác minh email' : 'Đặt lại mật khẩu'; user.otpHash = hashOtp(code); user.otpPurpose = purpose; user.otpExpiresAt = new Date(Date.now() + 10 * 60 * 1000); await user.save(); await sendEmail({to:user.email,subject:`PSIFU – ${title}`,text:`Mã OTP PSIFU của bạn là: ${code}. Mã có hiệu lực trong 10 phút. Không chia sẻ mã này cho bất kỳ ai.`,html:`<div style="font-family:Arial,sans-serif;background:#f4f7ff;padding:32px;color:#152a4d"><div style="max-width:520px;margin:auto;background:#fff;border-radius:16px;padding:30px"><div style="font-size:22px;font-weight:800;color:#155eef">PSIFU</div><h2>${title}</h2><p>Xin chào ${user.fullName || 'bạn'},</p><p>Dùng mã OTP dưới đây để tiếp tục. Mã có hiệu lực trong <b>10 phút</b>.</p><div style="font-size:32px;letter-spacing:8px;font-weight:800;color:#155eef;background:#eef3ff;padding:18px;border-radius:12px;text-align:center">${code}</div><p style="font-size:13px;color:#64748b;margin-top:24px">Không chia sẻ mã này cho bất kỳ ai, kể cả người tự xưng là PSIFU.</p></div></div>`}); };
const validateOtp = (user, purpose, code) => user && user.otpPurpose === purpose && user.otpExpiresAt > new Date() && user.otpHash === hashOtp(String(code || ''));
