app.get('/api/courses', async (req, res) => { const filter = { major: req.query.major || 'Computing', specialization: req.query.specialization || 'SE' }; if (req.query.track !== undefined) filter.track = req.query.track; if (req.query.term) filter.term = req.query.term; res.json((await Course.find(filter).sort({ term: 1, code: 1 })).map(toClient)); });
const releaseClient=release=>{const item=toClient(release);return {id:item.id,version:item.version,platform:item.platform,apkUrl:item.apkUrl,fileSizeBytes:item.fileSizeBytes,sha256:item.sha256,releaseNotes:item.releaseNotes||[],minSupportedVersion:item.minSupportedVersion,isForcedUpdate:item.isForcedUpdate,status:item.status,publishedAt:item.publishedAt,createdAt:item.createdAt,updatedAt:item.updatedAt};};
const releaseInput=body=>{const version=String(body.version||'').trim();const apkUrl=String(body.apkUrl||'').trim();const status=String(body.status||'DRAFT');if(!/^v?\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/.test(version))throw new Error('Version phải theo SemVer, ví dụ 1.0.0 hoặc v1.1.0.');if(apkUrl&&!/^https?:\/\//i.test(apkUrl))throw new Error('URL APK phải bắt đầu bằng http:// hoặc https://.');if(!['DRAFT','PUBLISHED','ARCHIVED'].includes(status))throw new Error('Trạng thái release không hợp lệ.');const notes=Array.isArray(body.releaseNotes)?body.releaseNotes:String(body.releaseNotes||'').split('\n');return {version,platform:'android',apkUrl,fileSizeBytes:Math.max(0,Number(body.fileSizeBytes)||0),sha256:String(body.sha256||'').trim().toLowerCase(),releaseNotes:notes.map(note=>String(note).trim()).filter(Boolean).slice(0,30),minSupportedVersion:String(body.minSupportedVersion||'').trim(),isForcedUpdate:Boolean(body.isForcedUpdate),status};};
