app.post('/api/admin/releases',requireAuth,requireRole('admin'),async(req,res)=>{try{const input=releaseInput(req.body);if(input.status==='PUBLISHED'&&!input.apkUrl)return res.status(400).json({success:false,msg:'Cần URL APK trước khi xuất bản release.'});const release=await AppRelease.create({...input,publishedAt:input.status==='PUBLISHED'?new Date():undefined});await AuditLog.create({actorEmail:req.auth.email,action:'APP_RELEASE_CREATED',targetType:'AppRelease',targetId:String(release._id),metadata:{version:release.version,status:release.status}});res.status(201).json({success:true,release:releaseClient(release)});}catch(error){res.status(error?.code===11000?409:400).json({success:false,msg:error?.code===11000?'Version này đã tồn tại.':error.message||'Không thể tạo release.'});}});
app.patch('/api/admin/releases/:id',requireAuth,requireRole('admin'),async(req,res)=>{try{const input=releaseInput(req.body);if(input.status==='PUBLISHED'&&!input.apkUrl)return res.status(400).json({success:false,msg:'Cần URL APK trước khi xuất bản release.'});const existing=await AppRelease.findById(req.params.id);if(!existing)return res.status(404).json({success:false,msg:'Không tìm thấy release.'});const publishedAt=input.status==='PUBLISHED'&&existing.status!=='PUBLISHED'?new Date():existing.publishedAt;const release=await AppRelease.findByIdAndUpdate(existing._id,{$set:{...input,publishedAt}},{new:true,runValidators:true});await AuditLog.create({actorEmail:req.auth.email,action:'APP_RELEASE_UPDATED',targetType:'AppRelease',targetId:String(release._id),metadata:{version:release.version,status:release.status}});res.json({success:true,release:releaseClient(release)});}catch(error){res.status(error?.code===11000?409:400).json({success:false,msg:error?.code===11000?'Version này đã tồn tại.':error.message||'Không thể cập nhật release.'});}});
