app.post('/api/users',authLimiter, async (req,res)=>{const email=cleanEmail(req.body.email),fullName=String(req.body.fullName||'').trim(),password=req.body.password,role=req.body.role||'mentee';if(!emailPattern.test(email))return res.status(400).json({success:false,msg:'Email không hợp lệ.'});if(fullName.length<2||fullName.length>80)return res.status(400).json({success:false,msg:'Họ tên phải từ 2 đến 80 ký tự.'});if(!validPassword(password))return res.status(400).json({success:false,msg:'Mật khẩu phải dài từ 8 đến 72 ký tự.'});if(!['mentee','mentor'].includes(role))return res.status(400).json({success:false,msg:'Vai trò đăng ký không hợp lệ.'});if(await User.exists({email}))return res.status(409).json({success:false,msg:'Email/Tài khoản này đã tồn tại!'});const user=await User.create({email,fullName,password:await bcrypt.hash(password,PASSWORD_HASH_ROUNDS),role,emailVerified:false,emailVerificationRequired:true,userXu:20,hasCheckedInToday:false,isFirstLogin:true});res.status(201).json({success:true,msg:'Đăng ký thành công! Hãy xác minh email.',user:toClient(user)});});
app.post('/api/auth/email-verification/send', otpLimiter, async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!user) return res.status(404).json({ success: false, msg: 'Không tìm thấy tài khoản với email này.' }); try { await issueOtp(user, 'verify-email'); res.json({ success: true, msg: 'Mã OTP đã được gửi tới email của bạn.' }); } catch (error) { res.status(503).json({ success: false, msg: error.message }); } });
app.post('/api/auth/email-verification/verify', async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!validateOtp(user, 'verify-email', req.body.code)) return res.status(400).json({ success: false, msg: 'Mã OTP không đúng hoặc đã hết hạn.' }); user.emailVerified = true; user.emailVerificationRequired = false; user.otpHash = undefined; user.otpPurpose = undefined; user.otpExpiresAt = undefined; await user.save(); res.json({ success: true, msg: 'Email đã được xác minh.' }); });
app.post('/api/auth/password-reset/send', otpLimiter, async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!user) return res.json({ success: true, msg: 'Nếu email thuộc tài khoản PSIFU, mã đặt lại mật khẩu sẽ được gửi.' }); try { await issueOtp(user, 'password-reset'); res.json({ success: true, msg: 'Nếu email thuộc tài khoản PSIFU, mã đặt lại mật khẩu sẽ được gửi.' }); } catch (error) { console.error('Password-reset OTP delivery failed:', error.message); res.status(503).json({ success: false, msg: 'Chưa thể gửi email lúc này. Vui lòng thử lại sau.' }); } });
app.post('/api/auth/password-reset/verify', async (req, res) => { const user = await User.findOne({ email: req.body.email?.trim().toLowerCase() }); if (!validateOtp(user, 'password-reset', req.body.code)) return res.status(400).json({ success: false, msg: 'Mã OTP không đúng hoặc đã hết hạn.' }); res.json({ success: true }); });
app.post('/api/auth/password-reset/complete', authLimiter, async (req,res)=>{const user=await User.findOne({email:cleanEmail(req.body.email)});if(!validPassword(req.body.password))return res.status(400).json({success:false,msg:'Mật khẩu phải dài từ 8 đến 72 ký tự.'});if(!validateOtp(user,'password-reset',req.body.code))return res.status(400).json({success:false,msg:'Mã OTP không đúng hoặc đã hết hạn.'});user.password=await bcrypt.hash(req.body.password,PASSWORD_HASH_ROUNDS);user.sessionVersion=(user.sessionVersion||0)+1;user.otpHash=undefined;user.otpPurpose=undefined;user.otpExpiresAt=undefined;await user.save();res.json({success:true,msg:'Đặt lại mật khẩu thành công. Các phiên đăng nhập cũ đã bị đăng xuất.'});});
