app.post('/api/uploads/cloudinary-signature',requireAuth,async(req,res)=>{const email=req.auth.email;if(cleanEmail(req.body.email)!==email)return res.status(403).json({success:false,msg:'Bạn chỉ được tải tài liệu cho chính mình.'});const user=await User.findOne({email});if(!user||user.role!=='mentor')return res.status(403).json({success:false,msg:'Chỉ Mentor được tải tài liệu lên.'});if(!cloudinaryConfigured())return res.status(503).json({success:false,msg:'Cloudinary chưa được cấu hình trên máy chủ.'});const fileName=String(req.body.fileName||'document.pdf');if(!fileName.toLowerCase().endsWith('.pdf'))return res.status(400).json({success:false,msg:'PSIFU chỉ hỗ trợ tệp PDF.'});const timestamp=Math.floor(Date.now()/1000);const safeEmail=email.replace(/[^a-z0-9]/gi,'_');const params={folder:`psifu/mentor-documents/${safeEmail}`,public_id:`doc_${timestamp}_${crypto.randomUUID().slice(0,8)}`,timestamp};res.json({success:true,cloudName:process.env.CLOUDINARY_CLOUD_NAME,apiKey:process.env.CLOUDINARY_API_KEY,timestamp,folder:params.folder,publicId:params.public_id,signature:cloudinarySignature(params)});});
app.post('/api/uploads/avatar-signature',requireAuth,async(req,res)=>{if(!cloudinaryConfigured())return res.status(503).json({success:false,msg:'Cloudinary chưa được cấu hình trên máy chủ.'});const timestamp=Math.floor(Date.now()/1000);const safeEmail=req.auth.email.replace(/[^a-z0-9]/gi,'_');const params={folder:'psifu/avatars',public_id:`avatar_${safeEmail}`,overwrite:true,timestamp};res.json({success:true,cloudName:process.env.CLOUDINARY_CLOUD_NAME,apiKey:process.env.CLOUDINARY_API_KEY,timestamp,folder:params.folder,publicId:params.public_id,signature:cloudinarySignature(params)});});
app.post('/api/payments/payos/topups',requireAuth, async (req,res) => { const email=req.auth.email; const coins=Number(req.body.coins); const packages=[50,100,200,500]; if(cleanEmail(req.body.email)!==email||!packages.includes(coins)) return res.status(400).json({success:false,msg:'Gói nạp không hợp lệ.'}); if(!payosConfigured()) return res.status(503).json({success:false,msg:'PayOS chưa được cấu hình trên máy chủ. Hãy thêm PAYOS_CLIENT_ID, PAYOS_API_KEY, PAYOS_CHECKSUM_KEY, PAYOS_RETURN_URL và PAYOS_CANCEL_URL.'}); const user=await User.findOne({email}); if(!user) return res.status(404).json({success:false,msg:'Không tìm thấy tài khoản.'}); try { const orderCode=await nextPayosOrderCode(); const amount=coins*1000; const requestData={orderCode,amount,description:`PSIFU ${coins} Xu`,returnUrl:process.env.PAYOS_RETURN_URL,cancelUrl:process.env.PAYOS_CANCEL_URL,items:[{name:`PSIFU ${coins} Xu`,quantity:1,price:amount}]}; requestData.signature=payosSignature({orderCode,amount,description:requestData.description,returnUrl:requestData.returnUrl,cancelUrl:requestData.cancelUrl}); const payment=await payosRequest('/v2/payment-requests',{method:'POST',body:JSON.stringify(requestData)}); const order=await PaymentOrder.create({orderCode,userEmail:email,coins,amount,paymentLinkId:payment.paymentLinkId,checkoutUrl:payment.checkoutUrl}); await AuditLog.create({actorEmail:email,action:'PAYOS_TOPUP_CREATED',targetType:'PaymentOrder',targetId:String(order.orderCode),metadata:{coins,amount}}); res.status(201).json({success:true,orderCode:order.orderCode,checkoutUrl:order.checkoutUrl,qrCode:payment.qrCode,amount:order.amount,status:order.status}); } catch(error){ console.error('PayOS create payment link:',error.message); res.status(502).json({success:false,msg:error.message||'Không thể tạo liên kết PayOS.'}); } });
app.get('/api/payments/payos/orders/:orderCode',requireAuth, async (req,res) => { const order=await PaymentOrder.findOne({orderCode:Number(req.params.orderCode)}); if(!order|| (order.userEmail!==req.auth.email&&req.auth.role!=='admin')) return res.status(404).json({success:false,msg:'Không tìm thấy đơn thanh toán.'}); res.json({success:true,orderCode:order.orderCode,status:order.status,coins:order.coins,amount:order.amount,userXu:order.status==='PAID'?(await User.findOne({email:order.userEmail}).select('userXu'))?.userXu:undefined}); });
app.post('/api/payments/payos/webhook', async (req,res) => { try { const payload=req.body||{}; const expected=payosSignature(payload.data||{}); const received=String(payload.signature||''); if(!received || expected.length!==received.length || !crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(received))) return res.status(400).json({success:false,msg:'Webhook signature không hợp lệ.'}); if(payload.code!=='00' || payload.success!==true || payload.data?.code!=='00') return res.status(200).json({success:true,ignored:true}); const existing=await PaymentOrder.findOne({orderCode:Number(payload.data.orderCode)}); if(!existing || existing.status==='PAID') return res.status(200).json({success:true,ignored:true}); if(existing.amount!==Number(payload.data.amount)) return res.status(400).json({success:false,msg:'Số tiền webhook không khớp đơn hàng.'}); const order=await PaymentOrder.findOneAndUpdate({orderCode:existing.orderCode,status:'PENDING'},{$set:{status:'PAID',reference:payload.data.reference,paidAt:new Date()}},{new:true}); if(!order) return res.status(200).json({success:true,ignored:true}); const user=await User.findOneAndUpdate({email:order.userEmail},{$inc:{userXu:order.coins}},{new:true}); if(!user) return res.status(404).json({success:false}); await Transaction.create({userEmail:user.email,type:'PAYOS_TOPUP',amount:order.coins,status:'SUCCESS',metadata:{orderCode:order.orderCode,amountVnd:order.amount,reference:order.reference}}); await Notification.create({userEmail:user.email,title:'Nạp Xu thành công',body:`PayOS đã xác nhận đơn #${order.orderCode}. ${order.coins} Xu đã được cộng vào ví.`,type:'WALLET'}); res.status(200).json({success:true}); } catch(error){ console.error('PayOS webhook:',error.message); res.status(500).json({success:false,msg:'Không thể xử lý webhook.'}); } });
app.put('/api/mentors/:email/bank-account',requireAuth,requireSelfOrAdmin(),async(req,res)=>{const email=req.params.email.trim().toLowerCase(),bank=req.body.bankAccount||{};const required=['bankName','accountNumber','accountHolder'];if(required.some(key=>!String(bank[key]||'').trim()))return res.status(400).json({success:false,msg:'Hãy nhập đủ ngân hàng, số tài khoản và tên chủ tài khoản.'});if(!/^\d{6,19}$/.test(String(bank.accountNumber)))return res.status(400).json({success:false,msg:'Số tài khoản phải gồm 6–19 chữ số.'});const user=await User.findOneAndUpdate({email,role:'mentor'},{$set:{bankAccount:{bankName:String(bank.bankName).trim(),accountNumber:String(bank.accountNumber).trim(),accountHolder:String(bank.accountHolder).trim().toUpperCase(),bin:String(bank.bin||'').trim()}}},{new:true});if(!user)return res.status(404).json({success:false,msg:'Không tìm thấy tài khoản Mentor.'});res.json({success:true,bankAccount:user.bankAccount});});
