app.post('/api/mentors/:email/bank-accounts',requireAuth,requireSelfOrAdmin(),async(req,res)=>{const email=req.params.email.toLowerCase(),bank=req.body.bankAccount||{};if(!String(bank.bankName||'').trim()||!/^\d{6,19}$/.test(String(bank.accountNumber||''))||!String(bank.accountHolder||'').trim())return res.status(400).json({success:false,msg:'Ngân hàng, số tài khoản (6–19 chữ số) và chủ tài khoản là bắt buộc.'});const user=await User.findOne({email,role:'mentor'}).lean();if(!user)return res.status(404).json({success:false,msg:'Không tìm thấy tài khoản Mentor.'});const accounts=user.bankAccounts?.length?user.bankAccounts:(user.bankAccount?.accountNumber?[{...user.bankAccount,id:'legacy'}]:[]);if(accounts.some(item=>item.accountNumber===String(bank.accountNumber)))return res.status(409).json({success:false,msg:'Tài khoản này đã tồn tại.'});const account={id:crypto.randomUUID(),bankName:String(bank.bankName).trim(),accountNumber:String(bank.accountNumber),accountHolder:String(bank.accountHolder).trim().toUpperCase(),bin:String(bank.bin||'').trim()};accounts.push(account);await User.collection.updateOne({_id:user._id},{$set:{bankAccounts:accounts,bankAccount:user.bankAccount?.accountNumber?user.bankAccount:account}});res.status(201).json({success:true,accounts,selectedAccountNumber:(user.bankAccount||account).accountNumber});});
app.patch('/api/mentors/:email/bank-accounts/:accountId/select',requireAuth,requireSelfOrAdmin(),async(req,res)=>{const user=await User.findOne({email:req.params.email.toLowerCase(),role:'mentor'}).lean();if(!user)return res.status(404).json({success:false});const accounts=user.bankAccounts?.length?user.bankAccounts:(user.bankAccount?.accountNumber?[{...user.bankAccount,id:'legacy'}]:[]);const account=accounts.find(item=>item.id===req.params.accountId);if(!account)return res.status(404).json({success:false,msg:'Không tìm thấy tài khoản.'});await User.collection.updateOne({_id:user._id},{$set:{bankAccounts:accounts,bankAccount:account}});res.json({success:true,bankAccount:account});});
app.post('/api/payouts',async(req,res)=>{const email=req.auth.email,amountXu=Number(req.body.amountXu);if(cleanEmail(req.body.email)!==email||!Number.isInteger(amountXu)||amountXu<50)return res.status(400).json({success:false,msg:'Số Xu rút tối thiểu là 50 Xu.'});const user=await User.findOneAndUpdate({email,role:'mentor',availableXu:{$gte:amountXu},'bankAccount.accountNumber':{$exists:true,$ne:''}},{$inc:{availableXu:-amountXu}},{new:true});if(!user)return res.status(400).json({success:false,msg:'Số dư khả dụng không đủ hoặc bạn chưa thêm tài khoản ngân hàng.'});try{const payoutCode=`PO-${Date.now()}-${crypto.randomUUID().slice(0,6).toUpperCase()}`;const payout=await Payout.create({payoutCode,mentorEmail:email,amountXu,amountVnd:amountXu*1000,bankAccount:user.bankAccount,status:'PROCESSING'});await Transaction.create({userEmail:email,type:'MENTOR_PAYOUT',amount:-amountXu,status:'PROCESSING',metadata:{payoutCode,bankName:user.bankAccount.bankName,accountNumber:user.bankAccount.accountNumber}});await AuditLog.create({actorEmail:email,action:'PAYOUT_CREATED',targetType:'Payout',targetId:payoutCode,metadata:{amountXu,amountVnd:payout.amountVnd}});await Notification.create({userEmail:email,title:'Yêu cầu rút Xu đang xử lý',body:`Lệnh ${payoutCode} rút ${amountXu} Xu đang chờ đối soát.`,type:'WALLET'});res.status(201).json({success:true,payout:toClient(payout),availableXu:user.availableXu});}catch(error){await User.findOneAndUpdate({email},{$inc:{availableXu:amountXu}});throw error;}});
