app.get('/api/premium/subscription/:email',requireAuth,requireSelfOrAdmin(),async(req,res)=>{const user=await User.findOne({email:req.params.email.toLowerCase()});if(!user)return res.status(404).json({success:false});res.json(subscriptionState(user));});
app.post('/api/premium/mock-payment/complete',requireAuth,async(req,res)=>{if(process.env.NODE_ENV==='production')return res.status(404).json({success:false,msg:'Phương thức thanh toán không khả dụng.'});if(cleanEmail(req.body.email)!==req.auth.email)return res.status(403).json({success:false,msg:'Bạn chỉ được thao tác trên tài khoản của chính mình.'});const user=await User.findOne({email:req.auth.email});if(!user)return res.status(404).json({success:false});const startedAt=new Date();const expiresAt=new Date(startedAt.getTime()+PREMIUM_PLAN.durationDays*86400000);user.subscription={plan:'PREMIUM',status:'ACTIVE',startedAt,expiresAt};await user.save();await Transaction.create({userEmail:user.email,type:'PREMIUM_SUBSCRIPTION',amount:PREMIUM_PLAN.price,status:'SUCCESS',metadata:{mode:'VNPAY_MOCK'}});await Notification.create({userEmail:user.email,title:'Chào mừng đến PSIFU Premium!',body:'Premium của bạn đã được kích hoạt.',type:'PREMIUM'});res.json({success:true,subscription:subscriptionState(user)});});
app.get('/api/premium/documents/:email',requireAuth,requireSelfOrAdmin(),async(req,res)=>{const user=await User.findOne({email:req.params.email.toLowerCase()});if(!isPremiumUser(user))return res.status(403).json({success:false,code:'PREMIUM_REQUIRED',message:'Tài nguyên này cần PSIFU Premium.'});res.json((await PremiumDocument.find()).map(toClient));});
app.post('/api/quiz/access',requireAuth,async(req,res)=>{if(cleanEmail(req.body.email)!==req.auth.email)return res.status(403).json({success:false,msg:'Bạn chỉ được sử dụng lượt quiz của chính mình.'});const user=await User.findById(req.auth.sub);if(!user)return res.status(404).json({success:false});const period=new Date().toISOString().slice(0,7);if(user.aiQuizUsagePeriod!==period){user.aiQuizUsagePeriod=period;user.aiQuizUsage=0;}const limit=isPremiumUser(user)?PREMIUM_PLAN.premiumAiQuizLimit:PREMIUM_PLAN.freeAiQuizLimit;if(user.aiQuizUsage>=limit){await user.save();return res.status(429).json({success:false,code:isPremiumUser(user)?'LIMIT_REACHED':'PREMIUM_REQUIRED',limit});}user.aiQuizUsage+=1;await user.save();res.json({success:true,remaining:limit-user.aiQuizUsage,plan:subscriptionState(user).plan});});
app.get('/api/notifications/:email',requireAuth,requireSelfOrAdmin(),async(req,res)=>res.json((await Notification.find({userEmail:req.params.email.toLowerCase()}).sort({createdAt:-1}).limit(30)).map(toClient)));
app.patch('/api/notifications/:id/read',requireAuth,async(req,res)=>res.json({success:!!await Notification.findOneAndUpdate({_id:req.params.id,userEmail:req.auth.email},{read:true})}));
app.get('/api/questions', async (_req, res) => res.json((await Question.find().sort({ createdAt: -1 })).map(toClient)));
app.post('/api/questions',requireAuth, async (req, res) => {const question=String(req.body.question||'').trim();if(!question||question.length>2000)return res.status(400).json({success:false,msg:'Nội dung câu hỏi không hợp lệ.'});res.status(201).json(toClient(await Question.create({question,menteeName:String(req.body.menteeName||'').slice(0,80),major:String(req.body.major||'').slice(0,80),currentTerm:String(req.body.currentTerm||'').slice(0,40)})));});
app.get('/api/bookings',requireAuth, async (req, res) => { const filter=req.auth.role==='admin'?{}:req.auth.role==='mentor'?{mentorEmail:req.auth.email}:{$or:[{menteeEmail:req.auth.email},{menteeName:(await User.findById(req.auth.sub).select('fullName'))?.fullName}]}; res.json((await Booking.find(filter).sort({ createdAt: -1 })).map(toClient)); });
app.get('/api/mentors/:email/availability',requireAuth,async(req,res)=>{const mentorEmail=cleanEmail(req.params.email);const date=String(req.query.date||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return res.status(400).json({success:false,msg:'Ngày phải theo định dạng YYYY-MM-DD.'});const mentor=await User.findOne({email:mentorEmail,role:'mentor'}).select('mentorAvailability');if(!mentor)return res.status(404).json({success:false,msg:'Không tìm thấy Mentor.'});const occupied=await Booking.find({mentorEmail,dateTime:{$regex:`^${date.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')} `},status:{$ne:'Đã hủy'}}).select('dateTime');const day=['Chủ Nhật','Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy'][new Date(`${date}T00:00:00`).getDay()];const ranges=mentor.mentorAvailability?.accepting===false?[]:(mentor.mentorAvailability?.slots?.find(slot=>slot.day===day)?.ranges||[]);res.json({success:true,date,accepting:mentor.mentorAvailability?.accepting!==false,ranges,occupiedTimes:occupied.map(item=>String(item.dateTime).split(' ')[1]).filter(Boolean)});});
app.post('/api/bookings',requireAuth, async (req, res) => { if(req.auth.role!=='mentee')return res.status(403).json({success:false,msg:'Chỉ Mentee có thể đặt lịch.'});const mentorEmail=cleanEmail(req.body.mentorEmail);const mentor=await User.findOne({email:mentorEmail,role:'mentor'}).select('fullName mentorFee mentorAvailability');const mentee=await User.findById(req.auth.sub).select('fullName userXu escrowXu');const dateTime=String(req.body.dateTime||'');const matched=dateTime.match(/^(\d{4}-\d{2}-\d{2})\s+(\d{2}:\d{2})$/);if(!mentor||!mentee||!matched)return res.status(400).json({success:false,msg:'Thông tin lịch hẹn không hợp lệ.'});const day=['Chủ Nhật','Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy'][new Date(`${matched[1]}T00:00:00`).getDay()];const ranges=mentor.mentorAvailability?.slots?.find(slot=>slot.day===day)?.ranges||[];const allowed=mentor.mentorAvailability?.accepting!==false&&ranges.some(range=>{const [from,to]=String(range).split('-').map(value=>value.trim());return from&&to&&matched[2]>=from&&matched[2]<to;});if(!allowed)return res.status(409).json({success:false,msg:'Mentor không mở lịch ở khung giờ này. Vui lòng chọn lịch trống khác.'});if(await Booking.exists({mentorEmail,dateTime,status:{$ne:'Đã hủy'}}))return res.status(409).json({success:false,msg:'Khung giờ này đã có mentee đặt trước.'});const fee=Number(mentor.mentorFee||50);const charged=await User.findOneAndUpdate({_id:mentee._id,userXu:{$gte:fee}},{$inc:{userXu:-fee,escrowXu:fee}},{new:true});if(!charged)return res.status(400).json({success:false,msg:'Bạn không đủ Xu để đặt lịch.'});try{const booking=await Booking.create({mentorEmail,mentorName:mentor.fullName,menteeName:mentee.fullName,menteeEmail:req.auth.email,course:String(req.body.course||'').slice(0,80),dateTime,note:String(req.body.note||'').trim().slice(0,2000),fee,meetingLink:'https://meet.google.com/psifu-session'});await Transaction.create({userEmail:req.auth.email,type:'BOOKING_ESCROW',amount:-fee,status:'HELD',metadata:{bookingId:String(booking._id),mentorEmail}});res.status(201).json({success:true,booking:toClient(booking),userXu:charged.userXu});}catch(error){await User.findByIdAndUpdate(mentee._id,{$inc:{userXu:fee,escrowXu:-fee}});throw error;}});
app.patch('/api/bookings/:id',requireAuth, async (req, res) => { const booking=await Booking.findById(req.params.id); if(!booking|| (req.auth.role!=='admin'&&booking.mentorEmail!==req.auth.email&&booking.menteeEmail!==req.auth.email))return res.status(404).json({success:false}); const allowed=req.auth.role==='mentor'||req.auth.role==='admin'?['Đã xác nhận','Đã hoàn thành','Đã hủy']:['Đã hủy']; if(!allowed.includes(req.body.status))return res.status(403).json({success:false,msg:'Bạn không có quyền cập nhật trạng thái này.'});if(booking.status===req.body.status)return res.json({success:true});if(req.body.status==='Đã hủy'&&booking.fee>0){await User.findOneAndUpdate({email:booking.menteeEmail},{$inc:{userXu:booking.fee,escrowXu:-booking.fee}});await Transaction.create({userEmail:booking.menteeEmail,type:'BOOKING_REFUND',amount:booking.fee,status:'SUCCESS',metadata:{bookingId:String(booking._id)}});}if(req.body.status==='Đã hoàn thành'&&booking.fee>0){await User.findOneAndUpdate({email:booking.menteeEmail},{$inc:{escrowXu:-booking.fee}});await User.findOneAndUpdate({email:booking.mentorEmail},{$inc:{availableXu:booking.fee}});await Transaction.create({userEmail:booking.mentorEmail,type:'BOOKING_RELEASE',amount:booking.fee,status:'SUCCESS',metadata:{bookingId:String(booking._id)}});}booking.status=req.body.status;await booking.save();res.json({success:true}); });
app.post('/api/bookings/:id/rating',requireAuth,async(req,res)=>{const booking=await Booking.findOne({_id:req.params.id,menteeEmail:req.auth.email});const score=Number(req.body.score);const comment=String(req.body.comment||'').trim();if(!booking)return res.status(404).json({success:false,msg:'Không tìm thấy lịch hẹn.'});if(booking.status!=='Đã hoàn thành')return res.status(409).json({success:false,msg:'Chỉ đánh giá sau khi buổi học hoàn thành.'});if(booking.rating?.score)return res.status(409).json({success:false,msg:'Buổi học này đã được đánh giá.'});if(!Number.isInteger(score)||score<1||score>5)return res.status(400).json({success:false,msg:'Vui lòng chọn từ 1 đến 5 sao.'});booking.rating={score,comment:comment.slice(0,1000),createdAt:new Date()};await booking.save();res.status(201).json({success:true,rating:booking.rating});});
app.get('/api/chats/:roomId',requireAuth,requireChatParticipant, async (req, res) => res.json((await ChatMessage.find({ roomId: req.params.roomId }).sort({ createdAt: 1 }).limit(25)).map(toClient)));
app.post('/api/chats/:roomId',requireAuth,requireChatParticipant, async (req, res) => { const text=String(req.body.text||'').trim();if(!text||text.length>2000)return res.status(400).json({success:false,msg:'Nội dung tin nhắn không hợp lệ.'});const role=req.auth.role==='mentor'?'MENTOR':req.auth.role==='admin'?'ADMIN':'MENTEE';const message=toClient(await ChatMessage.create({ roomId:req.params.roomId,user:String(req.body.user||'').slice(0,80),authorEmail:req.auth.email,role,text }));io.to(req.params.roomId).emit('chat:message',message);res.status(201).json(message); });
const catalogDocument = doc => { const item=toClient(doc); delete item.fileUri; delete item.cloudinaryPublicId; return item; };
app.get('/api/mentor-documents', async (req, res) => { const catalog=req.query.catalog==='true'; if(catalog){const documents=await MentorDocument.find({status:'PUBLISHED'}).sort({createdAt:-1});return res.json(documents.map(catalogDocument));} return requireAuth(req,res,async()=>{const filter=req.auth.role==='admin'?{}:{mentorEmail:req.auth.email}; if(req.query.status)filter.status=req.query.status; const documents=await MentorDocument.find(filter).sort({createdAt:-1});res.json(documents.map(toClient));}); });
app.post('/api/mentor-documents',requireAuth,requireRole('mentor','admin'), async (req, res) => { if(req.auth.role!=='admin'&&cleanEmail(req.body.mentorEmail)!==req.auth.email)return res.status(403).json({success:false,msg:'Bạn chỉ được tạo tài liệu của chính mình.'}); const document=await MentorDocument.create({...req.body,mentorEmail:req.auth.role==='admin'?cleanEmail(req.body.mentorEmail):req.auth.email});await AuditLog.create({actorEmail:req.auth.email,action:'MENTOR_DOCUMENT_CREATED',targetType:'MentorDocument',targetId:String(document._id),metadata:{status:document.status,title:document.title}});res.status(201).json(toClient(document));});
app.patch('/api/mentor-documents/:id',requireAuth,requireRole('mentor','admin'),async(req,res)=>{const document=await MentorDocument.findById(req.params.id);if(!document||(req.auth.role!=='admin'&&document.mentorEmail!==req.auth.email))return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu.'});const allowed=['title','course','category','description','fee','previewPages','status'];for(const key of allowed)if(req.body[key]!==undefined)document[key]=req.body[key];await document.save();await AuditLog.create({actorEmail:req.auth.email,action:'MENTOR_DOCUMENT_UPDATED',targetType:'MentorDocument',targetId:String(document._id),metadata:{status:document.status,title:document.title}});res.json({success:true,document:toClient(document)});});
app.delete('/api/mentor-documents/:id',requireAuth,requireRole('mentor','admin'),async(req,res)=>{const document=await MentorDocument.findById(req.params.id);if(!document||(req.auth.role!=='admin'&&document.mentorEmail!==req.auth.email))return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu.'});await DocumentUnlock.deleteMany({documentId:document._id});await MentorDocument.deleteOne({_id:document._id});await AuditLog.create({actorEmail:req.auth.email,action:'MENTOR_DOCUMENT_DELETED',targetType:'MentorDocument',targetId:String(document._id),metadata:{title:document.title}});res.json({success:true});});
app.get('/api/document-unlocks/:email',async(req,res)=>{const unlocks=await DocumentUnlock.find({userEmail:req.params.email.toLowerCase()}).select('documentId');res.json(unlocks.map(item=>String(item.documentId)));});
app.post('/api/mentor-documents/:id/unlock',requireAuth,async(req,res)=>{const email=req.auth.email;if(cleanEmail(req.body.email)!==email)return res.status(403).json({success:false,msg:'Bạn chỉ được mở khóa cho chính mình.'});const document=await MentorDocument.findOne({_id:req.params.id,status:'PUBLISHED'});if(!document)return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu đã xuất bản.'});const exists=await DocumentUnlock.exists({userEmail:email,documentId:document._id});if(exists)return res.json({success:true,alreadyUnlocked:true,userXu:(await User.findOne({email}).select('userXu'))?.userXu});const fee=Number(document.fee||0);const user=await User.findOneAndUpdate({email,userXu:{$gte:fee}},{$inc:{userXu:-fee}},{new:true});if(!user)return res.status(400).json({success:false,msg:'Bạn không đủ Xu để mở khóa tài liệu.'});try{await DocumentUnlock.create({userEmail:email,documentId:document._id});await MentorDocument.findByIdAndUpdate(document._id,{$inc:{unlocks:1,revenue:fee}});await Transaction.create({userEmail:email,type:'DOCUMENT_UNLOCK',amount:-fee,status:'SUCCESS',metadata:{documentId:String(document._id),title:document.title}});await AuditLog.create({actorEmail:email,action:'DOCUMENT_UNLOCKED',targetType:'MentorDocument',targetId:String(document._id),metadata:{fee,title:document.title}});res.status(201).json({success:true,userXu:user.userXu});}catch(error){await User.findOneAndUpdate({email},{$inc:{userXu:fee}});if(error?.code===11000)return res.json({success:true,alreadyUnlocked:true,userXu:(await User.findOne({email}).select('userXu'))?.userXu});throw error;}});
app.get('/api/mentor-documents/:id/access',requireAuth,async(req,res)=>{const email=req.auth.email;if(cleanEmail(req.query.email)!==email)return res.status(403).json({success:false,msg:'Bạn chỉ được đọc tài liệu đã mở khóa của chính mình.'});const document=await MentorDocument.findOne({_id:req.params.id,status:'PUBLISHED'});if(!document)return res.status(404).json({success:false,msg:'Không tìm thấy tài liệu.'});const unlocked=Number(document.fee||0)===0||await DocumentUnlock.exists({userEmail:email,documentId:document._id});if(!unlocked)return res.status(403).json({success:false,msg:'Hãy mở khóa tài liệu trước.'});res.json({success:true,document:{...catalogDocument(document),fileUri:document.fileUri}});});
app.use((err, _req, res, _next) => { console.error(err); res.status(500).json({ success: false, msg: 'Lỗi máy chủ.' }); });
const port = process.env.PORT || 4000;
mongoose.connect(process.env.MONGODB_URI).then(async () => { await User.bulkWrite(systemUsers.map(user => ({ updateOne: { filter: { email: user.email }, update: { $setOnInsert: user }, upsert: true } }))); await User.updateMany({email:{$in:systemUsers.map(user=>user.email)}},{$set:{emailVerified:true}}); await Course.collection.dropIndex('code_1').catch(() => null); await Course.collection.dropIndex('code_1_major_1_specialization_1').catch(() => null); await Course.collection.createIndex({ code: 1, major: 1, specialization: 1, track: 1 }, { unique: true }); await Course.bulkWrite(allCourseSeeds.map(course => ({ updateOne: { filter: { code: course.code, major: course.major, specialization: course.specialization, track: course.track }, update: { $set: course }, upsert: true } }))); server.listen(port, '0.0.0.0', () => console.log(`PSIFU API is running on port ${port}`)); }).catch(error => { console.error('Không thể kết nối MongoDB:', error.message); process.exit(1); });
